package at.andrew.squashtap;
import android.app.*;import android.content.*;import android.os.Looper;import android.view.*;import android.widget.*;import java.util.*;import java.util.concurrent.TimeUnit;import org.json.JSONObject;
import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.android.controller.ActivityController;import org.robolectric.annotation.*;import org.robolectric.shadows.ShadowDialog;import org.robolectric.util.ReflectionHelpers;import androidx.wear.widget.SwipeDismissFrameLayout;
import static org.junit.Assert.*;import static org.robolectric.Shadows.shadowOf;
@RunWith(RobolectricTestRunner.class) @Config(sdk=34,application=Application.class,qualifiers="w233dp-h233dp-round") @LooperMode(LooperMode.Mode.PAUSED) @GraphicsMode(GraphicsMode.Mode.LEGACY)
public class SettingsAndSharingUiTest {
 private ActivityController<MainActivity> controller;private MainActivity a;private SharedPreferences p;private LiveScoreClient client;private LiveScoreClientUiTest.Queue q;private boolean failCreate;private final List<LiveScoreClientUiTest.Call> calls=new ArrayList<>();
 @Before public void setup(){p=RuntimeEnvironment.getApplication().getSharedPreferences("squash",0);MatchBook b=new MatchBook(new MatchState("current",3));b.add(0);p.edit().clear().putString("match_book",b.encode()).putString("opponent_book",new OpponentDirectory().encode()).putString(MatchDisplayPolicy.ACTIVE_MATCH,"current").putBoolean("asked_match_notification",true).commit();q=new LiveScoreClientUiTest.Queue();client=new LiveScoreClient(RuntimeEnvironment.getApplication(),(method,path,token,body)->{calls.add(new LiveScoreClientUiTest.Call(method,path,token,body));if(failCreate&&method.equals("POST"))throw new java.io.IOException("Offline");return new JSONObject().put("expiresAt",System.currentTimeMillis()+3600000);},q);ReflectionHelpers.setStaticField(LiveScoreClient.class,"instance",client);controller=Robolectric.buildActivity(MainActivity.class).setup();a=controller.get();a.action(TouchTargets.MENU);}
 @After public void done(){client.stop(true);q.runAll();Dialog d=ShadowDialog.getLatestDialog();if(d!=null)d.dismiss();controller.pause().stop().destroy();ReflectionHelpers.setStaticField(LiveScoreClient.class,"instance",null);}
 private List<View> all(View v){List<View> list=new ArrayList<>();list.add(v);if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++)list.addAll(all(((ViewGroup)v).getChildAt(i)));return list;}
 private Button button(String label){for(View v:all(ShadowDialog.getLatestDialog().getWindow().getDecorView()))if(v instanceof Button&&((Button)v).getText().toString().startsWith(label))return(Button)v;throw new AssertionError("Missing "+label);}
 private void click(String label){button(label).performClick();shadowOf(Looper.getMainLooper()).idle();}
 private String page(){return ReflectionHelpers.getField(a,"panelPage");}
 private void start(){click("Current match");click("Live scoreboard");click("Start live sharing");assertEquals("Live scoreboard",page());}
 private void network(){q.runAll();shadowOf(Looper.getMainLooper()).idle();}
 private void back(){Dialog d=ShadowDialog.getLatestDialog();d.dispatchKeyEvent(new KeyEvent(KeyEvent.ACTION_DOWN,KeyEvent.KEYCODE_BACK));d.dispatchKeyEvent(new KeyEvent(KeyEvent.ACTION_UP,KeyEvent.KEYCODE_BACK));shadowOf(Looper.getMainLooper()).idle();}
 private void swipe(){for(View v:all(ShadowDialog.getLatestDialog().getWindow().getDecorView()))if(v instanceof SwipeDismissFrameLayout){ReflectionHelpers.callInstanceMethod(v,"performDismissFinishedCallbacks");shadowOf(Looper.getMainLooper()).idle();return;}throw new AssertionError("No swipe container");}
 @Test public void vibrationChoicesStayOpenShowTheirTickAndPreserveScore(){String book=p.getString("match_book","");click("Settings");click("Vibrations:");click("Off");assertEquals("Vibrations",page());assertTrue(button("✓ Off").isSelected());click("✓ Off");assertEquals("Vibrations",page());click("Point confirmation");assertEquals("points",p.getString("haptic_mode",""));assertTrue(button("✓ Point confirmation").isSelected());assertEquals(book,p.getString("match_book",""));assertEquals("current",p.getString(MatchDisplayPolicy.ACTIVE_MATCH,""));click("Back to Settings");assertNotNull(button("Vibrations: Point confirmation"));}
 @Test public void reminderAndDisplayChoicesStayOpenAndBackAndSwipeReturnToSettings(){click("Settings");click("Court and interval reminders:");click("On");assertEquals("Match reminders",page());assertTrue(button("✓ On").isSelected());back();assertEquals("Settings",page());click("Keep screen on: ON");click("Allow screen to sleep");assertEquals("Screen during play",page());assertTrue(button("✓ Allow screen to sleep").isSelected());swipe();assertNotNull(button("Keep screen on: OFF"));}
 @Test public void settingsReturnsToItsCallerAfterChangingAPreference(){click("Settings");click("Vibrations:");click("Off");back();click("Back to Menu");assertEquals("Menu",page());click("Change sport");click("Settings");click("Vibrations:");click("Points and milestones");swipe();click("Back to sports");assertEquals("Choose sport",page());}
 @Test public void liveReadinessOpensAudienceQrAutomaticallyAndOnlyOnce(){start();network();assertEquals("Audience QR",page());back();assertEquals("Live scoreboard",page());assertNotNull(button("Show audience QR"));ReflectionHelpers.callInstanceMethod(a,"onLiveStatusChanged",ReflectionHelpers.ClassParameter.from(String.class,"old status"));assertEquals("Live scoreboard",page());}
 @Test public void liveCreationFailureAutomaticallyRestoresTheStartAction(){failCreate=true;start();network();assertEquals("Live scoreboard",page());assertNull(client.session());assertNotNull(button("Start live sharing"));}
 @Test public void lateLiveCreationCannotReopenAnAbandonedMenu(){start();click("Back to Current match");click("Back to Menu");click("Players");String before=page();network();assertEquals(before,page());assertTrue(client.session().ready);}
 @Test public void backgroundReadinessWaitsUntilTheActivityReturns(){start();controller.pause();network();assertEquals("Live scoreboard",page());controller.resume();shadowOf(Looper.getMainLooper()).idle();assertEquals("Audience QR",page());}
 @Test public void autoQrReleasesItsTemporaryScreenRetention(){start();network();Dialog qr=ShadowDialog.getLatestDialog();assertTrue((qr.getWindow().getAttributes().flags&WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON)!=0);shadowOf(Looper.getMainLooper()).idleFor(61,TimeUnit.SECONDS);assertEquals(0,qr.getWindow().getAttributes().flags&WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);}
 @Test public void discardPublishesAnAnonymousNoticeAfterTheWatchCommit()throws Exception{start();network();LiveScoreClient.Session s=client.session();back();click("Back to Current match");click("Cancel match");click("Discard match");network();MatchBook b=MatchBook.decode(p.getString("match_book",""));assertEquals(0,b.count());assertFalse(b.current().hasPoints());LiveScoreClientUiTest.Call last=calls.get(calls.size()-1);JSONObject d=new JSONObject(TransferCrypto.open(s.id,"out",s.key,last.body.getString("cipher")));assertEquals("discarded",d.getString("phase"));assertEquals(2,d.length());}
 @Test public void cancellingDiscardKeepsTheBroadcastAndTheScore(){start();network();LiveScoreClient.Session s=client.session();String before=p.getString("match_book","");back();click("Back to Current match");click("Cancel match");click("Keep playing");network();assertSame(s,client.session());assertEquals(before,p.getString("match_book",""));assertFalse(s.discarded);}
}
